@startuml

class Family {
  + Name
  + Address
  + Telephone
  + InsuranceCarrier
  + PolicyNumber
}

class Patient {
  + Name
  + Gender
  + Birthdate
  + Allergies
  + Notes
}

class Appointment {
  + Date
  + Time
  + Reason
}

class Visit {
  + Diagnosis
  + Treatment
}

class Medication {
  + Name
  + Dosage
}

class Doctor {
  + Name
  + Specialty
  + Address
  + Telephone
  + PagerNumber
  + SSN
}

class Receptionist {
  + Name
}

class Nurse {
  + Name
}

class DoctorUser {
  + Name
}

Family "1" -- "1..*" Patient : has
Family "1" -- "0..1" Doctor : hasPrimaryCare
Patient "1" -- "0..*" Appointment : scheduled_for
Patient "1" -- "0..*" Visit : undergoes
Visit "1" -- "1..*" Medication : prescribed_during
Doctor "1..*" -- "0..*" Patient : sees_during_visit

@enduml

